<?php
require __DIR__ . '/client-common.php';

$showAll=isset($_GET['all']) && $_GET['all']==='1';
$q=trim((string)($_GET['q'] ?? '')); if (strlen($q)>120) $q=substr($q,0,120);
if ($q !== '') { $s=$pdo->prepare('SELECT id,client_name,telephone,full_address,vat_number,master_client_id FROM clients WHERE (client_name LIKE ? OR telephone LIKE ? OR full_address LIKE ?) ORDER BY client_name,id LIMIT 250'); $like='%'.$q.'%';$s->execute([$like,$like,$like]); }
else { $s=$pdo->query('SELECT id,client_name,telephone,full_address,vat_number,master_client_id FROM clients ORDER BY client_name,id LIMIT 250'); }
$rows=$s->fetchAll(PDO::FETCH_ASSOC);
if (!$showAll) { $rows=array_values(array_filter($rows, static fn($r)=>empty($r['master_client_id']))); }

?>
