<?php require __DIR__ . '/theme-ui.php'; ?><div class="wrap"><h1>Clients</h1><div class="bar"><a class="btn" href="jobs.php">← Jobs</a><a class="btn" href="client-edit.php">+ New Client</a><a class="btn" href="link-clients.php">Link Existing Jobs</a><a class="btn" href="clients.php?all=<?= $showAll ? '0' : '1' ?>"><?= $showAll ? 'Show Masters Only' : 'Show All Clients' ?></a><form method="get"><input name="q" placeholder="Search client, telephone or address" value="<?= h($q) ?>"><button>Search</button></form></div><?php if(isset($_GET['saved'])): ?><p>Client saved successfully.</p><?php endif; ?><?php if(isset($_GET['deleted'])): ?><p>Client deleted.</p><?php endif; ?><p class="muted">Showing <?= count($rows) ?> clients<?= $q===''?' (first 250; use search for others)':'' ?>.</p><table><thead><tr><th>Client</th><th>Telephone</th><th>Address</th><th>VAT #</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= h($r['client_name']) ?></td><td><?= h($r['telephone']) ?></td><td><?= nl2br(h($r['full_address'])) ?></td><td><?= h($r['vat_number']) ?></td><td><a href="client-edit.php?id=<?= (int)$r['id'] ?>">Edit</a> · <a href="client-master-manage.php?id=<?= (int)$r['id'] ?>">Master / Linked</a> · <a href="client-history.php?id=<?= (int)$r['id'] ?>">Job History</a></td></tr><?php endforeach; ?></tbody></table></div></body></html>
